using std::size_t;

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Guard against malformed input with fewer than N*N elements.
    if (A.size() / N < N) {
        return 0;
    }

    int max_degree = 0;

    #pragma omp parallel for default(none) shared(A, N) reduction(max:max_degree) schedule(static)
    for (size_t i = 0; i < N; ++i) {
        int degree = 0;
        const size_t row_start = i * N;

        for (size_t j = 0; j < N; ++j) {
            degree += A[row_start + j];
        }

        if (degree > max_degree) {
            max_degree = degree;
        }
    }

    return max_degree;
}
